function ending(kind){state.ending=true;overlay.style.display='flex';let title,text,buttons='';if(kind==='accept'){title='Döngünün Kabulleni';text='Kuzey, şehrin ve Ela’nın bu ritimle var olduğunu anlıyor. Çekirdeği olduğu gibi bırakıyor. Evine döner, yatağına uzanır. Saat 23:59 olur; yeni sabaha gülümseyerek uyanır. Sonsuz keşif modu açıldı.';buttons='<button onclick="window.donguContinue()">Yeni sabaha uyan</button>'}else if(kind==='wake'){title='Gerçek Dünyaya Dönüş';text='Kuzey çekirdeği tam vaktinde kapatıyor. Piksel odasının görüntüsü usulca çözülüyor. Gerçek bir hastane odasında gözlerini açıyor. Doktor gülümseyerek, “Beş yıllık derin uykudan uyandın, geçmiş olsun,” diyor.';buttons='<button onclick="window.donguContinue()">Anıları koru</button>'}else{title='Zamanın Gardiyanı';text='Kuzey bilincini çekirdeğe emanet ediyor. Şehrin ritmi yumuşakça dengelenirken, penceresinin dışında yeni uyanan kendisini izliyor. Artık her sabahın koruyucusu.';buttons='<button onclick="window.donguContinue()">Yeni döngüyü gör</button>'}card.innerHTML=`<h1>${title}</h1><p>${text}</p><div class="choices">${buttons}<button class="secondary" onclick="window.donguClose()">Bu anı sakla</button></div>`;}
window.donguContinue=()=>{overlay.style.display='none';state.mem.add('Son: '+(state.ending?'tamamlandı':''));resetLoop('Yeni bir sabah başlıyor. Önceki günün tüm bilgileri yanında.','');};window.donguClose=()=>{overlay.style.display='none';say('Bu an günlüğüne işlendi. Şehir sakin bir ritimle devam ediyor.');renderActions()};
function openJournal(){overlay.style.display='flex';const memories=[...state.mem];card.innerHTML=`<h1>Hafıza Defteri</h1><p>Her yeni döngüde bilgiler ve açılan ipuçları seninle kalır. Bugün ${String(Math.floor(state.time/60)).padStart(2,'0')}:${String(state.time%60).padStart(2,'0')}.</p><div class="memories">${memories.length?memories.map(m=>`<span class="memory">✦ ${m}</span>`).join(''):'<span class="memory">Henüz bir ipucu yok</span>'}</div><div class="choices"><button class="secondary" onclick="window.donguClose()">Günlüğe dön</button></div>`}
document.querySelector('#journalBtn').onclick=openJournal;
document.querySelector('#restartBtn').onclick=()=>{if(confirm('Yeni bir döngüye başlansın mı? Birikmiş anıların korunur.'))resetLoop('Alarmın sesiyle gözlerini açıyorsun. Bu kez yanında önceki günlerin bilgileri var.','manual')};
document.querySelector('#interact').onclick=()=>{const first=actions.querySelector('.action');if(first)first.click();else say('Şu an etkileşime açık bir nesne yok.');};
const dirBtns=[...document.querySelectorAll('[data-dir]')];function setMove(d){moving=d;}
dirBtns.forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);setMove(b.dataset.dir)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>{moving=null}))});
function tick(t){if(!last)last=t;const dt=Math.min(.05,(t-last)/1000);last=t;if(moving){const v=dt*.42;if(moving==='up')state.y-=v;if(moving==='down')state.y+=v;if(moving==='left')state.x-=v;if(moving==='right')state.x+=v;state.x=Math.max(.08,Math.min(.92,state.x));state.y=Math.max(.16,Math.min(.9,state.y));scenePulse+=dt;draw()}raf=requestAnimationFrame(tick)}
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0);draw()}
window.addEventListener('resize',resize);requestAnimationFrame(tick);
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);let s=state.scene;
const gradients={room:['#26383a','#17272b'],hall:['#344044','#202e31'],street:['#637276','#3c5056'],park:['#344d47','#213b39'],metro:['#273b43','#15272e'],lab:['#29363b','#17262c'],core:['#203a40','#101f28']};let g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,gradients[s][0]);g.addColorStop(1,gradients[s][1]);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
// atmospheric pixel-art ground / architecture
const scale=Math.max(2,Math.floor(w/170));ctx.globalAlpha=.2;for(let i=0;i<65;i++){let x=(i*67+23)%w,y=(i*97+11)%h;ctx.fillStyle=i%3?'#d8d1b3':'#7eb8a7';ctx.fillRect(x,y,scale,scale)}ctx.globalAlpha=1;
if(s==='room'){ctx.fillStyle='#504744';ctx.fillRect(w*.08,h*.08,w*.84,h*.84);ctx.fillStyle='#39484a';ctx.fillRect(w*.11,h*.11,w*.78,h*.78);ctx.fillStyle='#d3b777';ctx.fillRect(w*.12,h*.13,w*.25,h*.19);ctx.fillStyle='#95b7b2';ctx.fillRect(w*.135,h*.145,w*.22,h*.16);ctx.fillStyle='#72645a';ctx.fillRect(w*.56,h*.12,w*.29,h*.17);ctx.fillStyle='#a48963';ctx.fillRect(w*.59,h*.15,w*.23,h*.11);ctx.fillStyle='#465756';ctx.fillRect(w*.24,h*.52,w*.52,h*.29);ctx.fillStyle='#9a8d7b';ctx.fillRect(w*.27,h*.49,w*.46,h*.13);ctx.fillStyle='#dbcba8';ctx.fillRect(w*.32,h*.51,w*.19,h*.09);ctx.fillStyle='#766550';ctx.fillRect(w*.76,h*.63,w*.13,h*.2);}
if(s==='hall'){ctx.fillStyle='#615a51';ctx.fillRect(0,h*.25,w,h*.46);for(let i=0;i<4;i++){ctx.fillStyle=i===1?'#846c54':'#3b4544';ctx.fillRect(w*(.08+i*.23),h*.29,w*.16,h*.39);ctx.fillStyle='#d2b879';ctx.fillRect(w*(.1+i*.23),h*.36,w*.12,h*.015)}ctx.fillStyle='#9c8565';ctx.fillRect(w*.45,h*.1,w*.1,h*.08)}
if(s==='street'){ctx.fillStyle='#637174';ctx.fillRect(0,h*.12,w,h*.44);ctx.fillStyle='#283638';ctx.fillRect(0,h*.53,w,h*.47);ctx.fillStyle='#b8aa87';ctx.fillRect(w*.1,h*.62,w*.8,h*.025);for(let i=0;i<5;i++){ctx.fillStyle='#d8d2b9';ctx.fillRect(w*(.17+i*.14),h*.65,w*.07,h*.08)}ctx.fillStyle='#1c272c';ctx.fillRect(w*.65,h*.43,w*.22,h*.11);ctx.fillStyle='#8fa3a1';ctx.fillRect(w*.68,h*.45,w*.07,h*.035);ctx.fillRect(w*.79,h*.45,w*.05,h*.035)}
if(s==='park'){ctx.fillStyle='#52604e';ctx.fillRect(0,h*.48,w,h*.52);ctx.fillStyle='#8b826c';ctx.beginPath();ctx.moveTo(w*.44,h);ctx.lineTo(w*.58,h);ctx.lineTo(w*.53,h*.42);ctx.lineTo(w*.48,h*.42);ctx.fill();for(let i=0;i<7;i++){let x=(i*91+25)%w,y=h*(.2+(i%3)*.1);ctx.fillStyle='#253d39';ctx.fillRect(x,y,w*.12,h*.25);ctx.fillStyle='#4b6452';ctx.fillRect(x-w*.025,y-h*.06,w*.17,h*.17)}ctx.fillStyle='#816c55';ctx.fillRect(w*.25,h*.58,w*.5,h*.055);ctx.fillRect(w*.29,h*.635,w*.035,h*.13);ctx.fillRect(w*.68,h*.635,w*.035,h*.13)}
if(s==='metro'){ctx.fillStyle='#182a30';ctx.fillRect(0,h*.15,w,h*.62);ctx.fillStyle='#516166';ctx.fillRect(0,h*.3,w,h*.05);ctx.fillStyle='#26373b';ctx.fillRect(0,h*.73,w,h*.27);ctx.fillStyle='#8c846b';ctx.fillRect(0,h*.71,w,h*.025);for(let i=0;i<8;i++){ctx.fillStyle='#9dc4b8';ctx.fillRect(w*(.08+i*.12),h*.22,3,5)}ctx.fillStyle='#b0a276';ctx.fillRect(w*.12,h*.43,w*.18,h*.19);ctx.fillStyle='#283c3e';ctx.fillRect(w*.14,h*.46,w*.14,h*.1)}
if(s==='lab'){ctx.fillStyle='#435056';ctx.fillRect(w*.08,h*.12,w*.84,h*.7);for(let i=0;i<3;i++){ctx.fillStyle='#26383c';ctx.fillRect(w*(.15+i*.25),h*.24,w*.17,h*.32);ctx.fillStyle='#65a992';ctx.fillRect(w*(.17+i*.25),h*.27,w*.13,h*.07);ctx.fillStyle='#d5bc7e';ctx.fillRect(w*(.17+i*.25),h*.4,w*.1,h*.015)}ctx.fillStyle='#859187';ctx.fillRect(w*.39,h*.76,w*.22,h*.06)}
if(s==='core'){ctx.fillStyle='#364b4b';ctx.fillRect(w*.08,h*.12,w*.84,h*.77);let pulse=Math.sin(scenePulse*2)*4;ctx.strokeStyle='#7ed0b5';ctx.lineWidth=5;ctx.beginPath();ctx.arc(w*.5,h*.48,Math.min(w,h)*.2+pulse,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#d1b86d';ctx.lineWidth=2;ctx.beginPath();ctx.arc(w*.5,h*.48,Math.min(w,h)*.13-pulse*.3,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#b4dec3';ctx.fillRect(w*.47,h*.45,w*.06,h*.06);ctx.fillStyle='#8d967d';ctx.fillRect(w*.2,h*.75,w*.6,h*.08)}

