}
function ending(kind){state.ending=true;overlay.style.display='flex';let title,text;if(kind==='accept'){title='Döngünün Kabulleni';text='Kuzey, şehrin ve Ela’nın bu ritimle var olduğunu anlıyor. Çekirdeği olduğu gibi bırakıyor. Evine döner, yatağına uzanır. Saat 23:59 olur; yeni sabaha gülümseyerek uyanır. Sonsuz keşif modu açıldı.'}else if(kind==='wake'){title='Gerçek Dünyaya Dönüş';text='Kuzey çekirdeği tam vaktinde kapatıyor. Piksel odasının görüntüsü usulca çözülüyor. Gerçek bir hastane odasında gözlerini açıyor. Doktor gülümseyerek, “Beş yıllık derin uykudan uyandın, geçmiş olsun,” diyor.'}else{title='Zamanın Gardiyanı';text='Kuzey bilincini çekirdeğe emanet ediyor. Şehrin ritmi yumuşakça dengelenirken, penceresinin dışında yeni uyanan kendisini izliyor. Artık her sabahın koruyucusu.'}card.innerHTML=`<h1>${title}</h1><p>${text}</p><div class="choices"><button onclick="window.donguContinue()">Yeni sabaha uyan</button><button class="secondary" onclick="window.donguClose()">Bu anı sakla</button></div>`;}
window.donguContinue=()=>{overlay.style.display='none';state.mem.add('Son: tamamlandı');resetLoop('Yeni bir sabah başlıyor. Önceki günün tüm bilgileri yanında.','')};window.donguClose=()=>{overlay.style.display='none';say('Bu an günlüğüne işlendi. Şehir sakin bir ritimle devam ediyor.');renderActions()};
function openJournal(){overlay.style.display='flex';let memories=[...state.mem];card.innerHTML=`<h1>Hafıza Defteri</h1><p>Her yeni döngüde bilgiler ve açılan ipuçları seninle kalır. Bugün ${clockEl.textContent}.</p><div class="memories">${memories.length?memories.map(m=>`<span class="memory">✦ ${m}</span>`).join(''):'<span class="memory">Henüz bir ipucu yok</span>'}</div><div class="choices"><button class="secondary" onclick="window.donguClose()">Günlüğe dön</button></div>`}
document.querySelector('#journalBtn').onclick=openJournal;
document.querySelector('#restartBtn').onclick=()=>{if(confirm('Yeni bir döngüye başlansın mı? Birikmiş anıların korunur.'))resetLoop('Alarmın sesiyle gözlerini açıyorsun. Bu kez yanında önceki günlerin bilgileri var.','manual')};
document.querySelector('#interact').onclick=()=>{let first=actions.querySelector('.action');if(first)first.click();else say('Şu an etkileşime açık bir nesne yok.')};
const dirBtns=[...document.querySelectorAll('[data-dir]')];let moving=null;dirBtns.forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);moving=b.dataset.dir});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>moving=null))});
function tick(){if(moving){let v=.007;if(moving==='up')state.y-=v;if(moving==='down')state.y+=v;if(moving==='left')state.x-=v;if(moving==='right')state.x+=v;state.x=Math.max(.08,Math.min(.92,state.x));state.y=Math.max(.16,Math.min(.9,state.y));draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);

